public List<List<Integer>> Permute(int[] nums)
{
    List<List<Integer>> result = new List<List<Integer>>();
    if (nums == null || nums.Length == 0)
    {
        return result;
    }
    List<Integer> comb = new List<Integer>();
    // Each element in the array is a potential starting point for a permutation
    for (int i = 0; i < nums.Length; i++)
    {
        // Add the current element to the combination
        comb.Add(nums[i]);
        // Recursively permute the remaining elements
        List<List<Integer>> nextCombs = Permute(nums, i + 1, nums.Length - 1);
        // Add the permutations to the result
        foreach (List<Integer> nextComb in nextCombs)
        {
            result.Add(comb.Concat(nextComb).ToList());
        }
        // Backtrack and remove the current element from the combination
        comb.RemoveAt(comb.Count - 1);
    }
    return result;
}

private List<List<Integer>> Permute(int[] nums, int start, int end)
{
    List<List<Integer>> result = new List<List<Integer>>();
    if (start == end)
    {
        result.Add(new List<Integer>());
    }
    else
    {
        // Each element in the remaining array is a potential starting point for a permutation
        for (int i = start; i <= end; i++)
        {
            // Add the current element to the combination
            Swap(nums, start, i);
            // Recursively permute the remaining elements
            List<List<Integer>> nextCombs = Permute(nums, start + 1, end);
            // Add the permutations to the result
            foreach (List<Integer> nextComb in nextCombs)
            {
                result.Add(new List<Integer>(nums, start, end - start + 1).Concat(nextComb).ToList());
            }
            // Backtrack and remove the current element from the combination
            Swap(nums, start, i);
        }
    }
    return result;
}

