    Set<Integer> seen = new HashSet<>();
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@') {
                int id = i * grid[i].length + j;
                if (!seen.contains(id)) {
                    seen.add(id);
                    dfs(grid, i, j, id, seen);
                }
            }
        }
    }
    return seen.size();
}

