public static int maxRegions(int N) {
    // Initialize a 2D array to represent the plane
    boolean[][] plane = new boolean[N][N];

    // Initialize the maximum number of regions to 0
    int maxRegions = 0;

    // Iterate over each row of the plane
    for (int i = 0; i < N; i++) {
        // Iterate over each column of the plane
        for (int j = 0; j < N; j++) {
            // If the current cell is not yet visited
            if (!plane[i][j]) {
                // Start a new region and mark all cells in the region as visited
                dfs(plane, i, j, N);
                maxRegions++;
            }
        }
    }

    return maxRegions;
}

private static void dfs(boolean[][] plane, int i, int j, int N) {
    // Base case: If the current cell is out of bounds or already visited, return
    if (i < 0 || i >= N || j < 0 || j >= N || plane[i][j]) {
        return;
    }

    // Mark the current cell as visited
    plane[i][j] = true;

    // Recursively visit all adjacent cells
    dfs(plane, i - 1, j, N);
    dfs(plane, i + 1, j, N);
    dfs(plane, i, j - 1, N);
    dfs(plane, i, j + 1, N);
}

