public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Perform Breadth-First Search to check if the starting n-tersection is connected to the ending n-tersection
    Queue<int[]> queue = new LinkedList<>();
    Set<int[]> visited = new HashSet<>();
    queue.add(start);
    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }
        for (int[] neighbour : getNeighbours(n, current, paths)) {
            if (!visited.contains(neighbour)) {
                queue.add(neighbour);
                visited.add(neighbour);
            }
        }
    }
    return "cannot be travelled";
}

private static int[][] getNeighbours(int n, int[] node, int[][] paths) {
    int[][] neighbours = new int[4][2];
    for (int i = 0; i < 4; i++) {
        int x = node[0] + directions[i][0];
        int y = node[1] + directions[i][1];
        if (x >= 0 && x < n && y >= 0 && y < n && paths[x][y] != -1) {
            neighbours[i] = new int[] { x, y };
        }
    }
    return neighbours;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize variables needed
    boolean[] visited = new boolean[n];
    int[][] pathMatrix = new int[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            pathMatrix[i][j] = paths[i][j];
        }
    }

    // Use DFS to explore the n-teresting space
    dfs(start[0], start[1], visited, pathMatrix);

    // Check if the ending n-tersection has been visited
    if (visited[end[1]]) {
        return "Can be travelled";
    } else {
        return "Cannot be travelled";
    }
}

private static void dfs(int i, int j, boolean[] visited, int[][] pathMatrix) {
    // Terminate condition: if the current n-tersection is already visited
    if (visited[i][j]) {
        return;
    }

    // Mark the current n-tersection as visited
    visited[i][j] = true;

    // Recursively DFS to explore the unvisited neighboring n-tersections
    for (int k = 0; k < n; k++) {
        if (pathMatrix[i][k] != 0 && !visited[k]) {
            dfs(k, j, visited, pathMatrix);
        }
    }
}

