    // Initialize a boolean array to keep track of visited n-tersections
    boolean[] visited = new boolean[n];

    // Initialize the starting n-tersection as visited
    visited[start[0]] = true;

    // Perform a depth-first search to check if the ending n-tersection is reachable
    if (dfs(start, end, paths, visited)) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

private static boolean dfs(int[] current, int[] end, int[][] paths, boolean[] visited) {
    // If the current n-tersection is the ending n-tersection, return true
    if (Arrays.equals(current, end)) {
        return true;
    }

    // Mark the current n-tersection as visited
    visited[current[0]] = true;

    // Look for any unvisited n-tersection that is reachable from the current n-tersection
    for (int[] path : paths) {
        if (path[1] == current[0] && !visited[path[0]]) {
            visited[path[0]] = true;
            if (dfs(path, end, paths, visited)) {
                return true;
            }
        }
    }

    // If no unvisited n-tersection is reachable, return false
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
        // Initialize a visited array to keep track of the n-tersections visited
        boolean[][] visited = new boolean[n][n];

        // Initialize a queue to perform BFS iteratively
        Queue<Pair<Integer, Integer>> queue = new ArrayDeque<>();

        // Add the starting n-tersection to the queue and mark it as visited
        queue.add(new Pair<>(start[0], start[1]));
        visited[start[0]][start[1]] = true;

        while (!queue.isEmpty()) {
            // Dequeue the next n-tersection to visit
            Pair<Integer, Integer> current = queue.poll();

            // If the current n-tersection is the same as the ending n-tersection, return "can be travelled"
            if (current.getKey() == end[0] && current.getValue() == end[1]) {
                return "can be travelled";
            }

            // Add all reachable n-tersections to the queue and mark them as visited
            for (int[] path : paths) {
                int x = current.getKey();
                int y = current.getValue();
                int newX = x + path[0];
                int newY = y + path[1];

                if (newX >= 0 && newY >= 0 && newX < n && newY < n) {
                    queue.add(new Pair<>(newX, newY));
                    visited[newX][newY] = true;
                }
            }
        }

        // If no path has been found, return "cannot be travelled"
        return "cannot be travelled";
    }

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the starting and ending n-tersections are valid
    if (start.length != n || end.length != n) {
        return "cannot be travelled";
    }

    // Create a matrix to represent the n-teresting space
    boolean[][] matrix = new boolean[n][n];

    // Initialize the matrix with the given paths
    for (int i = 0; i < paths.length; i++) {
        for (int j = 0; j < paths[i].length; j++) {
            matrix[i][j] = paths[i][j] != 0;
        }
    }

    // Check if there is a path between the starting and ending n-tersections
    if (!isPathExists(matrix, start, end)) {
        return "cannot be travelled";
    }

    // Check if there are any closed loops in the matrix
    if (isLoopExists(matrix)) {
        return "cannot be travelled";
    }

    return "can be travelled";
}

