    while (left <= right) {
        int mid = (left + right) / 2;
        if (nums[mid] == target) {
            return mid;
        }

        // if the left half is sorted
        if (nums[left] <= nums[mid]) {
            // if the target is between nums[left] and nums[mid]
            if (target >= nums[left] && target <= nums[mid]) {
                right = mid - 1;
