public double trimMean(int[] arr) {
    Arrays.sort(arr);
    int n = arr.length;
    int trimmedLength = (int) Math.round(0.95 * (n - 2));
    int start = (int) Math.round(0.05 * n);
    int end = (int) Math.round(0.95 * n);
    double sum = 0;
    for (int i = start + 1; i < end; i++) {
        sum += arr[i];
    }
    return sum / trimmedLength;
}

public static double trimMean(int[] arr) {
    int n = arr.length;
    int threshold = (int) (n * 0.05);
    int[] sortedArr = Arrays.copyOf(arr, n);
    Arrays.sort(sortedArr);

    int sum = 0;
    for (int i = threshold; i < n - threshold; ++i) {
        sum += sortedArr[i];
    }

    return ((double) sum) / (n - 2 * threshold);
}

public double trimMean(double[] arr) {
    int n = arr.length;
    double mean = 0;
    double sum = 0;
    for (int i = 0; i < n; i++) {
        sum += arr[i];
        if (i == 0 || sum < arr[i]) {
