        }
        mean += arr[i] / sum;
    }
    return mean;
}

public boolean canArrange(int[] arr, int k) {
    // Special case: if k is 1, then the divisibility condition is always satisfied
    if (k == 1) {
        return true;
    }

    // Initialize a HashMap to store the remainder of each element when divided by k
    // The key is the remainder, and the value is the number of elements with that remainder
    Map<Integer, Integer> remainderCountMap = new HashMap<>();
    for (int i = 0; i < arr.length; i++) {
        int remainder = arr[i] % k;
        if (!remainderCountMap.containsKey(remainder)) {
            remainderCountMap.put(remainder, 1);
        } else {
            int count = remainderCountMap.get(remainder);
            remainderCountMap.put(remainder, count + 1);
        }
    }

    // Check if it is possible to divide the array into n/2 pairs such that the sum of each pair is divisible by k
    for (Map.Entry<Integer, Integer> entry : remainderCountMap.entrySet()) {
        int remainder = entry.getKey();
        int count = entry.getValue();

        // If there are more than 2 elements with the same remainder, then it is not possible to divide them into pairs
        if (count > 2) {
            return false;
        }

        // If there is only one element with the remainder, then it is not possible to find another element with the opposite remainder to form a pair
        if (count == 1) {
            int oppositeRemainder = (k - remainder) % k;
            if (!remainderCountMap.containsKey(oppositeRemainder)) {
                return false;
            }
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    // check if the array length is even and divisible by k
    if (arr.length % 2 != 0 || arr.length / k != 0) {
        return false;
    }

    // create a hash map to store the sums of the pairs
    Map<Integer, Integer> pairSums = new HashMap<>();

    // iterate through the array and calculate the sums of each pair
    for (int i = 0; i < arr.length; i += 2) {
        int sum = arr[i] + arr[i + 1];
        pairSums.put(sum, pairSums.getOrDefault(sum, 0) + 1);
    }

    // check if each pair sum is divisible by k
    for (Map.Entry<Integer, Integer> entry : pairSums.entrySet()) {
        if (entry.getValue() % k != 0) {
            return false;
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (k <= 0 || arr.length % 2 != 0) {
