    }
    int[] sums = new int[arr.length];
    for (int i = 0; i < arr.length - 1; i += 2) {
        sums[i] = arr[i] + arr[i + 1];
    }
    if (sums.length % 2 != 0) {
        return false;
    }
    for (int i = 0; i < sums.length; i += 2) {
        if (sums[i] % k != 0 || sums[i + 1] % k != 0) {
            return false;
        }
    }
    return true;
}

