public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int time = 0;

    // Initialize a visited array to keep track of which nodes have been visited
    boolean[] visited = new boolean[n];
    visited[0] = true;

    // Use a queue to perform a BFS of the tree
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(0);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        int currNode = queue.poll();
        int numChildren = 0;
        int childNode = -1;

        // Loop through the children of the current node
        for (int i = 0; i < edges.length; i++) {
            if (edges[i][0] == currNode) {
                childNode = edges[i][1];
                numChildren++;
            }
        }

        // If the current node has an apple, add the time it takes to visit it
        if (hasApple[currNode]) {
            time += numChildren;
        }

        // If the current node is not the last node, update the time
        if (currNode != n - 1) {
            time++;
        }

        // Add the child node to the queue to visit it next
        if (childNode != -1) {
