}

public String sortString(String s) {
    // Step 1: Pick the smallest character from s and append it to the result.
    String result = s.substring(0, 1);

    // Step 2: Pick the smallest character from s which is greater than the last appended character to the result and append it.
    int smallestIndex = 1;
    int largestIndex = s.length() - 1;
    while (smallestIndex <= largestIndex && s.charAt(smallestIndex) <= s.charAt(smallestIndex - 1)) {
        smallestIndex++;
    }
    while (largestIndex >= 0 && s.charAt(largestIndex) >= s.charAt(smallestIndex - 1)) {
        largestIndex--;
    }
    if (largestIndex > smallestIndex) {
        result += s.substring(smallestIndex, largestIndex + 1);
    }

    // Step 4: Pick the largest character from s and append it to the result.
    result += s.substring(s.length() - 1, s.length());

    // Step 5: Pick the largest character from s which is smaller than the last appended character to the result and append it.
    largestIndex--;
    while (largestIndex >= 0 && s.charAt(largestIndex) >= s.charAt(smallestIndex - 1)) {
        largestIndex--;
    }
    largestIndex++;
    if (largestIndex < smallestIndex) {
        result += s.substring(largestIndex, s.length());
    }

    // Step 7: Repeat steps 1 to 6 until you pick all characters from s.
    while (smallestIndex < s.length() && largestIndex > 0) {
        smallestIndex = 1;
        largestIndex -= 2;
        if (s.charAt(smallestIndex) <= s.charAt(smallestIndex - 1)) {
            break;
        }
        result += s.substring(smallestIndex, smallestIndex + 1);
    }
    while (largestIndex > 0) {
        largestIndex -= 2;
        if (s.charAt(largestIndex) <= s.charAt(smallestIndex - 1)) {
            break;
        }
        result += s.substring(largestIndex, largestIndex + 1);
    }

    return result;
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    while (result.length() < s.length()) {
        // Find the smallest character that can be appended
        char smallest = 'z' + 1;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) > smallest && s.charAt(i) < result.charAt(result.length() - 1)) {
                smallest = s.charAt(i);
            }
        }
        result.append(smallest);

        // Find the largest character that can be appended
        char largest = 'a' - 1;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) < largest && s.charAt(i) > result.charAt(result.length() - 1)) {
                largest = s.charAt(i);
            }
        }
        result.append(largest);
    }
    return result.toString();
}

public static String sortString(String s) {
        // create a list to hold the unique characters in s
        List<Character> chars = new ArrayList<>();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!chars.contains(c)) {
                chars.add(c);
            }
        }

        // sort the list according to the algorithm
        Collections.sort(chars);

        // create a string builder to hold the result
        StringBuilder result = new StringBuilder();

        // start with the smallest character and append it to the result
        result.append(chars.get(0));

        // initialize variables for the smallest and largest characters
        char smallest = chars.get(0);
        char largest = chars.get(chars.size() - 1);

        // iterate over the characters in the list and append them to the result
        for (int i = 1; i < chars.size() - 1; i++) {
            if (i % 2 == 0) {
                // if it's an even iteration, append the smallest character
                result.append(smallest);
                smallest = chars.get(i + 1);
            } else {
                // if it's an odd iteration, append the largest character
                result.append(largest);
                largest = chars.get(i - 1);
            }
        }

        // append the last character to the result
        result.append(chars.get(chars.size() - 1));

        return result.toString();
    }

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    char[] chars = s.toCharArray();
    Arrays.sort(chars);

    int i = 0;
    int j = chars.length - 1;
    StringBuilder result = new StringBuilder();

    while (i < j) {
        result.append(chars[i]);
        result.append(chars[j]);
        i++;
        j--;
    }

    if (j == i && chars[j] < chars[i - 1]) {
        result.append(chars[j]);
    }

    return result.toString();
}

public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    List<Character> sorted = new ArrayList<>(chars.length);
    while (sorted.size() < chars.length) {
        for (char c : chars) {
            if (!sorted.contains(c)) {
                sorted.add(c);
            }
        }
        for (int i = 0; i < sorted.size(); i++) {
            for (int j = i + 1; j < sorted.size(); j++) {
                if (sorted.get(i) > sorted.get(j)) {
                    char temp = sorted.get(i);
                    sorted.set(i, sorted.get(j));
                    sorted.set(j, temp);
                }
            }
        }
    }
    return sorted.toString();
}

