public int minCostClimbingStairs(int[] cost) {
    // Initialize the minimum cost to the maximum integer value
    int minCost = Integer.MAX_VALUE;

    // Initialize the previous minimum cost
    int prevMinCost = 0;

    // Loop through the cost array
    for (int i = 0; i < cost.length; i++) {
        // Calculate the current minimum cost
        int currMinCost = Math.min(prevMinCost + cost[i], cost[i]);

        // Update the previous minimum cost
        prevMinCost = minCost;

        // Update the minimum cost
        minCost = Math.min(minCost, currMinCost);
    }

    return minCost;
}

