private List<Integer> getFactors(int n) {
    List<Integer> factors = new ArrayList<Integer>();
    for (int i = 1; i <= Math.sqrt(n); i++) {
        if (n % i == 0) {
            factors.add(i);
            if (n / i != i) {
                factors.add(n / i);
            }
        }
    }
    Collections.sort(factors);
    return factors;
}

