public static String makeGood(String s) {
        int i = 0, j = s.length()-1;
        StringBuilder sb = new StringBuilder();
        int[] count = new int[26];
        // prepare array to count upper and lower case characters
        for (int k = 0; k < 26; k++) {
            count[k] = 0;
        }
        // count upper and lower case characters in s
        for (char c: s.toCharArray()) {
            if (c - 'A' >= 0 && c - 'A' < count.length) {
                count[c-'A']++;
            } else if (c - 'a' >= 0 && c - 'a' < count.length) {
                count[c-'a']++;
            }
        }
        // construct resulting string
        while (i <= j) {
            if (i == j) {
                sb.append((char)(i + 'A'));
                i++;
            } else {
                while (count[i] == 0 && i <= j) {
                    i++;
                }
                if (i <= j) {
                    sb.append((char)(i + 'A'));
                    count[i]--;
                }
                while (count[j] == 0 && j >= i) {
                    j--;
                }
                if (j >= i) {
                    sb.append((char)(j + 'A'));
                    count[j]--;
                }
            }
        }
        return sb.toString();
    }

