public String getSmallestString(int n, int k) {
    // edge case: n is not positive
    if (n <= 0) {
        return "";
    }

    // edge case: k is not positive
    if (k <= 0) {
        return "a".repeat(n);
    }

    // calculate the number of a's needed
    int numAs = (int) Math.floor((double) (k - 1) / (double) (n - 1));
    // calculate the number of b's needed
    int numBs = k - numAs - (n - 1);

    // create the string
    return "a".repeat(numAs) + "b".repeat(numBs) + "z".repeat(n - numBs);
}

