    // calculate the number of permutations
    double permutations = 1;
    for (int i = 1; i <= n; i++) {
        permutations *= i;
    }

    // calculate the number of arrangements where the last passenger sits in their own seat
    double arrangements = 1;
    for (int i = 1; i <= n - 1; i++) {
