        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j] = 1;
                int left = j - 1;
                int right = j + 1;
                while (left >= 0 && mat[i][left] == 1) {
                    dp[i][j]++;
                    left--;
                }
                while (right < n && mat[i][right] == 1) {
                    dp[i][j]++;
                    right++;
                }
                maxLength = Math.max(maxLength, dp[i][j]);
            }
        }
    }

    return maxLength;
}

