    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            int currLength = -1;

            // Horizontal
            if (j > 0 && currLength < 0) {
                currLength = -1;
            }

            // Vertical
            if (i > 0 && currLength < 0) {
                currLength = -1;
            }

            // Diagonal
            if (i < rows - 1 && j < cols - 1) {
                currLength = Math.max(currLength, mat[i][j] + mat[i + 1][j + 1]);
            }

            // Anti-diagonal
            if (i > 0 && j > 0) {
                currLength = Math.max(currLength, mat[i][j] + mat[i - 1][j - 1]);
            }

            maxLength = Math.max(maxLength, currLength);
        }
    }

    return maxLength;
}

