public static int largestRectangleArea(int[] heights) {
   /* Algorithm:
    * 1. Create a new list of heights and add 0 to both ends to serve as sentinels
    * 2. Initialize a stack to store indices of heights
    * 3. Iterate through the new list of heights
    *    3.a If the current height is greater than the height at the top of the stack, push the current index to the stack
    *    3.b If the current height is less than the height at the top of the stack, pop the top of the stack
    *     3.b.i Calculate the rectangle area with the height at the top of the stack as the minimum height
    *           and the current index minus the next index in the stack (or 0) as the width
    *     3.b.ii Add the rectangle area to the maximum area
    * 4. Return the maximum area
    */

   List<Integer> newHeights = new ArrayList<Integer>(heights.length + 2);
   newHeights.add(0);
   newHeights.addAll(heights);
   newHeights.add(0);
   Stack<Integer> stack = new Stack<Integer>();
   stack.add(0);
   int maxArea = 0;
   for (int i = 1; i < newHeights.size(); i++) {
       int height = newHeights.get(i);
       if (height > newHeights.get(stack.peek())) {
           stack.push(i);
       } else {
           int currentIndex = i;
           while (!stack.isEmpty() && newHeights.get(stack.peek()) > height) {
               int topIndex = stack.pop();
               int width = currentIndex - (stack.isEmpty() ? 0 : stack.peek());
               maxArea = Math.max(maxArea, width * height);
               currentIndex = topIndex;
           }
           stack.push(currentIndex);
       }
   }
   return maxArea;
}

