public static boolean isBoomerang(int[][] points) {
    // Check if the input array contains exactly 3 points
    if (points.length != 3) {
        return false;
    }
    // Check if the three points are collinear
    double a = points[1][0] - points[0][0];
    double b = points[1][1] - points[0][1];
    double c = points[2][0] - points[0][0];
    double d = points[2][1] - points[0][1];
    if (a * d == b * c) {
        return false;
    }
    // Check if the three points are not aligned vertically
    if (a == 0 || b == 0 || c == 0 || d == 0) {
        return false;
    }
    // Check if the segments formed by the points have the same slope
    if (a * d != b * c) {
        return false;
    }
    // Check if the three points are not aligned horizontally
    if (a == 0 || b == 0 || c == 0 || d == 0) {
        return false;
    }
    // Check if the segments formed by the points have the same slope
    if (a * d == b * c) {
        return false;
    }
    // If all checks pass, the points form a boomerang
    return true;
}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        return false;
    }
    int slope1 = getSlope(points[0][0], points[0][1], points[1][0], points[1][1]);
    int slope2 = getSlope(points[0][0], points[0][1], points[2][0], points[2][1]);
    return slope1 * slope2 == -1;
}

private static int getSlope(int x1, int y1, int x2, int y2) {
    return (y2 - y1) / (x2 - x1);
}

public static boolean isBoomerang(int[][] points) {
