  int x3 = points[2][0];
  int y3 = points[2][1];
  if (x1 == x2 && x2 == x3 && y1 == y2 && y2 == y3) {
    return false;
  }
  if (x1 == x2) {
    return (y1 - y2) * (x3 - x2) == (y3 - y2) * (x2 - x1);
  } else if (y1 == y2) {
    return (x1 - x2) * (y3 - y2) == (x3 - x2) * (y2 - y1);
  } else {
    return false;
  }
}

