}

public static int findNthUglyNumber(int n) {
    if (n <= 0) return -1;
    int[] uglyNumbers = new int[n+1];
    uglyNumbers[0] = 1;
    int index2 = 0;
    int index3 = 0;
    int index5 = 0;
    int nextUglyNumber;
    for (int i = 1; i < n; i++) {
        nextUglyNumber = Math.min(2 * uglyNumbers[index2], Math.min(3 * uglyNumbers[index3], 5 * uglyNumbers[index5]));
        uglyNumbers[i] = nextUglyNumber;
        if (nextUglyNumber == 2 * uglyNumbers[index2]) index2++;
        if (nextUglyNumber == 3 * uglyNumbers[index3]) index3++;
        if (nextUglyNumber == 5 * uglyNumbers[index5]) index5++;
    }
    return uglyNumbers[n-1];
}

