        nextUglyNumber = min;
        while (uglyNums[i2] * 2 <= nextUglyNumber) i2++;
        while (uglyNums[i3] * 3 <= nextUglyNumber) i3++;
        while (uglyNums[i5] * 5 <= nextUglyNumber) i5++;
    }
