}

public static int findNthUglyNumber(int n) {
    int i = 0;
    int j = 0;
    int k = 0;
    int count = 0;
    int uglyNumber = 0;

    while (count < n) {
        i = i * 2 + 1;
        j = j * 3 + 1;
        k = k * 5 + 1;

        int min = Math.min(i, Math.min(j, k));
        if (min == i) {
            count += 1;
            uglyNumber = i;
        } else if (min == j) {
            count += 1;
            uglyNumber = j;
        } else {
            count += 1;
            uglyNumber = k;
        }
    }

    return uglyNumber;
}

