public static int calculateEnergy(String s) {
    // Initialize variables
    int maxLength = 1;
    int currentLength = 1;
    char previousChar = s.charAt(0);

    // Iterate through the string
    for (int i = 1; i < s.length(); i++) {
        char currentChar = s.charAt(i);

        // Check if the current character is the same as the previous character
        if (currentChar == previousChar) {
            // If it is the same, increase the current length by 1
            currentLength++;
        } else {
            // If it is not the same, compare the current length with the max length
            if (currentLength > maxLength) {
                // If the current length is greater than the max length, update the max length
                maxLength = currentLength;
            }
            // Reset the current length to 1
            currentLength = 1;
        }

        // Update the previous character
        previousChar = currentChar;
    }

    // Compare the last character with the max length
    if (currentLength > maxLength) {
        maxLength = currentLength;
    }

    return maxLength;
}

