    for (int i = 1; i < s.length(); i++) {
        char currentChar = s.charAt(i);
        if (currentChar == previousChar) {
            currentCharEnergy++;
        } else {
            energy = Math.max(energy, currentCharEnergy);
            currentCharEnergy = 1;
        }
        previousChar = currentChar;
    }

    return Math.max(energy, currentCharEnergy);
}

