public static int minPerfectSquareSum(int n) {
    int count = 0;
    while (n > 0) {
        int root = (int) Math.sqrt(n);
        count++;
        n -= root * root;
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
        // Initialize a set to store the perfect square numbers
        Set<Integer> squareNumbers = new HashSet<>();
        for (int i = 1; i * i <= n; i++) {
            squareNumbers.add(i * i);
        }

        // Initialize a variable to store the minimum number of perfect square numbers
        int minCount = Integer.MAX_VALUE;

        // Iterate over the perfect square numbers and find the combination with the minimum count
        for (int i = 1; i <= n; i++) {
            if (squareNumbers.contains(i)) {
                minCount = Math.min(minCount, 1 + minPerfectSquareSum(n - i));
            }
        }

        return minCount;
    }

public static int minPerfectSquareSum(int n) {
        ArrayList<Integer> perfectSquares = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            perfectSquares.add(i * i);
        }

        int minSum = Integer.MAX_VALUE;
        int sum = 0;
        for (int i = 0; i < perfectSquares.size(); i++) {
            sum += perfectSquares.get(i);
            if (sum == n) {
                return i + 1;
            } else if (sum > n) {
                sum -= perfectSquares.get(i);
                i--;
                continue;
            }
        }

        return -1;
    }

public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
        HashMap<Integer, Integer> squares = new HashMap<>();
        int minSquares = 0;
        for (int i = 1; i <= n; i++) {
            int square = i * i;
            if (square > n) {
                break;
            }
            squares.put(square, i);
        }
        for (int i = n; i > 0; i--) {
            if (squares.containsKey(i)) {
                minSquares++;
                i -= squares.get(i);
            }
        }
        return minSquares;
    }

